import { BotSDK, deriveGatewayUrl } from '/app/sdk/index.ts';
import { BotActions } from '/app/sdk/actions.ts';
import { readFileSync, existsSync } from 'fs';
import { join } from 'path';

function loadBotEnv(botName: string) {
  const p = join('/app/bots', botName, 'bot.env');
  const content = readFileSync(p, 'utf-8');
  const env: Record<string, string> = {};
  for (const line of content.split('\n')) {
    const t = line.trim();
    if (!t || t.startsWith('#')) continue;
    const i = t.indexOf('=');
    if (i > 0) env[t.slice(0, i).trim()] = t.slice(i + 1).trim();
  }
  return env;
}

const env = loadBotEnv('agent');
const sdk = new BotSDK({
  botUsername: env.BOT_USERNAME,
  password: env.PASSWORD,
  gatewayUrl: deriveGatewayUrl(env.SERVER),
  autoReconnect: true,
} as any);
