async function mineOne(oreName, rockId) {
  for (let tries=0; tries<10; tries++) {
    const s = sdk.getState();
    const rock = s.nearbyLocs.filter(l=>l.id===rockId).sort((a,b)=>a.distance-b.distance)[0]
      || s.nearbyLocs.filter(l=>new RegExp(oreName,'i').test(l.name)).sort((a,b)=>a.distance-b.distance)[0];
    if (!rock) { console.log('no rock '+oreName); return false; }
    const opt = rock.optionsWithIndex.find(o=>/^mine$/i.test(o.text));
    await sdk.sendInteractLoc(rock.x, rock.z, rock.id, opt.opIndex);
    await sdk.waitForTicks(6);
    const inv = sdk.getInventory();
    if (inv.some(i=>new RegExp(oreName,'i').test(i.name))) { console.log('got '+oreName); return true; }
  }
  return false;
}
